// A ping that did not land is a failed execution, stated plainly. It is not
// alerted from here -- if this workflow cannot reach the monitor, the monitor
// notices the silence and alerts on its own, which is the whole design. The
// failed execution is the record for the human who then asks why.
const target = String($env.BETTERSTACK_HEARTBEAT_URL || '');
if (!target) throw new Error('BETTERSTACK_HEARTBEAT_URL is not set in the n8n environment; the heartbeat pinged nothing');
const res = $('PingHeartbeat').first().json || {};
const code = res.statusCode;
if (!(code >= 200 && code < 300)) {
  throw new Error('heartbeat ping failed: HTTP ' + (code == null ? 'none (transport error: ' + String(res.message || res.error || 'unknown').slice(0, 120) + ')' : code));
}
return [{ json: { ok: true, statusCode: code, pingedAt: new Date().toISOString() } }];
